            _lines = lines.GetEnumerator();
            this.dialect = dialect;
        }

        void SaveField()
        {
            string? f = _field.ToString();
            if (_unquoted && f.Length == 0 && (dialect.quoting == csv.QUOTE_NOTNULL || dialect.quoting == csv.QUOTE_STRINGS)) f = null;
            else if (_unquoted && f.Length > 0 && (dialect.quoting == csv.QUOTE_NONNUMERIC || dialect.quoting == csv.QUOTE_STRINGS))
                throw new NotSupportedException("Typhon: a csv.reader with quoting=QUOTE_NONNUMERIC or QUOTE_STRINGS (CPython makes unquoted fields floats; rows here are lists of str)");
            _fields!.Add(f!);
            _field.Clear();
            _unquoted = true;
        }

        void AddChar(int c)
        {
            if (_field.Length >= csv.FieldLimit) throw new csv.Error($"field larger than field limit ({csv.FieldLimit})");
            _field.Append((char)c);
        }

        bool Is(int c, string? ch) => ch != null && ch.Length == 1 && c == ch[0];

        void Process(int c)
        {
            var d = dialect;
            bool quoting = d.quoting != csv.QUOTE_NONE;
            switch (_state)
            {
                case State.StartRecord:
                    if (c == Eol) break;
                    if (c == '\n' || c == '\r') { _state = State.EatCrnl; break; }
                    _state = State.StartField;
                    goto case State.StartField;
                case State.StartField:
                    if (c == '\n' || c == '\r' || c == Eol) { SaveField(); _state = c == Eol ? State.StartRecord : State.EatCrnl; }
                    else if (Is(c, d.quotechar) && quoting) { _unquoted = false; _state = State.InQuotedField; }
                    else if (Is(c, d.escapechar)) _state = State.EscapedChar;
                    else if (c == ' ' && d.skipinitialspace) { }
                    else if (Is(c, d.delimiter)) SaveField();
                    else { AddChar(c); _state = State.InField; }
                    break;
                case State.EscapedChar:
                    if (c == '\n' || c == '\r') { AddChar(c); _state = State.AfterEscapedCrnl; break; }
                    if (c == Eol) c = '\n';
                    AddChar(c);
                    _state = State.InField;
                    break;
                case State.AfterEscapedCrnl:
                    if (c == Eol) break;
                    goto case State.InField;
                case State.InField:
                    if (c == '\n' || c == '\r' || c == Eol) { SaveField(); _state = c == Eol ? State.StartRecord : State.EatCrnl; }
                    else if (Is(c, d.escapechar)) _state = State.EscapedChar;
                    else if (Is(c, d.delimiter)) { SaveField(); _state = State.StartField; }
                    else AddChar(c);
                    break;
                case State.InQuotedField:
                    if (c == Eol) { }
                    else if (Is(c, d.escapechar)) _state = State.EscapeInQuotedField;
                    else if (Is(c, d.quotechar) && quoting) _state = d.doublequote ? State.QuoteInQuotedField : State.InField;
                    else AddChar(c);
                    break;
                case State.EscapeInQuotedField:
                    if (c == Eol) c = '\n';
                    AddChar(c);
                    _state = State.InQuotedField;
                    break;
                case State.QuoteInQuotedField:
                    if (quoting && Is(c, d.quotechar)) { AddChar(c); _state = State.InQuotedField; }
                    else if (Is(c, d.delimiter)) { SaveField(); _state = State.StartField; }
                    else if (c == '\n' || c == '\r' || c == Eol) { SaveField(); _state = c == Eol ? State.StartRecord : State.EatCrnl; }
                    else if (!d.strict) { AddChar(c); _state = State.InField; }
