            var r = _fields;
            _fields = null;
            return r;
        }

        public List<string> __next__() => Next() ?? throw new StopIteration();
        public List<string> Current => _current!;
        object IEnumerator.Current => _current!;
        public bool MoveNext() { _current = Next(); return _current != null; }
        public void Reset() => throw new NotSupportedException();
        public void Dispose() { }
        public IEnumerator<List<string>> GetEnumerator() => this;
