        readonly object _file;
        public readonly csv.Dialect dialect;

        public CsvWriter(object file, csv.Dialect dialect) { _file = file; this.dialect = dialect; }

        static bool IsNumber(object? v) => v is long || v is int || v is double || v is float || v is bool || v is BigInteger || v is decimal || v is Fraction ||
                                          v is short || v is byte || v is uint || v is ulong;

        static IEnumerable<object?> Fields(object? row)
