            {
                case null: throw new csv.Error("iterable expected, not NoneType");
                case string s: return s.Select(c => (object?)c.ToString());
                case System.Runtime.CompilerServices.ITuple t: return Enumerable.Range(0, t.Length).Select(i => t[i]);
                case IEnumerable e: return e.Cast<object?>();
                default: throw new csv.Error($"iterable expected, not {(row is long ? "int" : row is double ? "float" : row is bool ? "bool" : row.GetType().Name)}");
            }
        }

        /// <summary>One field appended to the record (join_append_data).</summary>
        void Append(StringBuilder rec, ref int numFields, string? field, bool quoted)
        {
            var d = dialect;
            char? delim = d.delimiter[0], quote = d.quotechar?[0], esc = d.escapechar?[0];
            var body = new StringBuilder();
            if (string.IsNullOrEmpty(field) && delim == ' ' && d.skipinitialspace)
            {
                if (d.quoting == csv.QUOTE_NONE || field == null && (d.quoting == csv.QUOTE_STRINGS || d.quoting == csv.QUOTE_NOTNULL))
                    throw new csv.Error("empty field must be quoted if delimiter is a space and skipinitialspace is true");
                quoted = true;
            }
            if (field != null)
                foreach (char c in field)
                {
                    bool wantEscape = false;
                    if (c == delim || c == esc || c == quote || c == '\n' || c == '\r' || d.lineterminator.IndexOf(c) >= 0)
                    {
                        if (d.quoting == csv.QUOTE_NONE) wantEscape = true;
                        else
                        {
                            if (c == quote) { if (d.doublequote) body.Append(c); else wantEscape = true; }
                            else if (c == esc) wantEscape = true;
                            if (!wantEscape) quoted = true;
                        }
                        if (wantEscape)
                        {
                            if (esc == null) throw new csv.Error("need to escape, but no escapechar set");
                            body.Append(esc.Value);
                        }
                    }
                    body.Append(c);
                }
            if (numFields > 0) rec.Append(delim.Value);
            if (quoted) rec.Append(quote).Append(body).Append(quote); else rec.Append(body);
            numFields++;
