namespace Typhon.Stdlib
{
    using System;
    using System.Collections;
    using System.Collections.Generic;
    using System.Linq;
    using Typhon.Runtime;

    /// <summary>The csv module: reader, writer, DictReader, DictWriter, dialects and the QUOTE_* constants.</summary>
    internal static class csv
    {
        public const long QUOTE_MINIMAL = 0, QUOTE_ALL = 1, QUOTE_NONNUMERIC = 2, QUOTE_NONE = 3, QUOTE_STRINGS = 4, QUOTE_NOTNULL = 5;
        public const string __version__ = "1.0";

        /// <summary>csv.Error</summary>
        internal sealed class Error : Exception { public Error(string message) : base(message) { } }

        internal static long FieldLimit = 128 * 1024;

        public static long field_size_limit() => FieldLimit;
        public static long field_size_limit(long new_limit) { long old = FieldLimit; FieldLimit = new_limit; return old; }

        /// <summary>A parameter left out (None is a value for quotechar and escapechar).</summary>
        internal const string Unset = "\x00unset";

        /// <summary>csv.Dialect: the formatting parameters of a reader or writer.</summary>
        internal sealed class Dialect : IPyRepr
        {
            public readonly string delimiter;
            public readonly string? quotechar, escapechar;
            public readonly bool doublequote, skipinitialspace, strict;
            public readonly string lineterminator;
            public readonly long quoting;

            readonly string? _class;

            public Dialect(string delimiter = ",", string? quotechar = "\"", string? escapechar = null, bool doublequote = true,
                           bool skipinitialspace = false, string lineterminator = "\r\n", long quoting = QUOTE_MINIMAL, bool strict = false)
                : this(delimiter, quotechar, escapechar, doublequote, skipinitialspace, lineterminator, quoting, strict, null) { }

            public Dialect(object dialect) : this(ReadDialect(dialect)) { }

            Dialect(Dialect source) : this(source.delimiter, source.quotechar, source.escapechar, source.doublequote,
                source.skipinitialspace, source.lineterminator, source.quoting, source.strict) { }

            internal Dialect(string delimiter, string? quotechar, string? escapechar, bool doublequote, bool skipinitialspace,
                             string lineterminator, long quoting, bool strict, string? className)
            {
                static void OneChar(string name, string? c, bool orNone)
                {
                    if (c == null && !orNone) throw new InvalidCastException($"\"{name}\" must be a unicode character, not NoneType");
                    if (c != null && c.Length != 1)
                        throw new InvalidCastException($"\"{name}\" must be a unicode character{(orNone ? " or None" : "")}, not a string of length {c.Length}");
                }
                OneChar("delimiter", delimiter, false);
                OneChar("quotechar", quotechar, true);
                OneChar("escapechar", escapechar, true);
                if (lineterminator == null) throw new InvalidCastException("\"lineterminator\" must be a string, not NoneType");
                if (quoting < 0 || quoting > QUOTE_NOTNULL) throw new InvalidCastException("bad \"quoting\" value");
                if (quoting != QUOTE_NONE && quotechar == null) throw new InvalidCastException("quotechar must be set if quoting enabled");
                // CPython's dialect_check_char / dialect_check_chars
                void Check(string name, string? c, bool allowSpace)
                {
                    if (c == null) return;
                    if (c[0] == '\r' || c[0] == '\n' || c[0] == ' ' && !allowSpace) throw new ArgumentException($"bad {name} value");
                    if (lineterminator.IndexOf(c[0]) >= 0) throw new ArgumentException($"bad {name} or lineterminator value");
                }
                static void Pair(string n1, string n2, string? c1, string? c2)
                {
                    if (c1 != null && c1 == c2) throw new ArgumentException($"bad {n1} or {n2} value");
                }
                Check("delimiter", delimiter, true);
                Check("escapechar", escapechar, !skipinitialspace);
                Check("quotechar", quotechar, !skipinitialspace);
                Pair("delimiter", "escapechar", delimiter, escapechar);
                Pair("delimiter", "quotechar", delimiter, quotechar);
                Pair("escapechar", "quotechar", escapechar, quotechar);
                this.delimiter = delimiter; this.quotechar = quotechar; this.escapechar = escapechar; this.doublequote = doublequote;
                this.skipinitialspace = skipinitialspace; this.lineterminator = lineterminator; this.quoting = quoting; this.strict = strict;
                _class = className;
            }

            internal Dialect With(string delimiter, string? quotechar, string? escapechar, bool? doublequote, bool? skipinitialspace,
                                  string lineterminator, long? quoting, bool? strict)
            {
                // quotechar=None without a quoting turns quoting off
                long q = quoting ?? (quotechar == null ? QUOTE_NONE : this.quoting);
                return new Dialect(delimiter == Unset ? this.delimiter : delimiter, quotechar == Unset ? this.quotechar : quotechar,
                                   escapechar == Unset ? this.escapechar : escapechar, doublequote ?? this.doublequote,
                                   skipinitialspace ?? this.skipinitialspace, lineterminator == Unset ? this.lineterminator : lineterminator,
                                   q, strict ?? this.strict, null);
            }

            public string __repr__() => _class != null ? $"<class 'csv.{_class}'>" : $"<_csv.Dialect object at 0x{System.Runtime.CompilerServices.RuntimeHelpers.GetHashCode(this):x12}>";
            public override string ToString() => __repr__();
        }

        public static readonly Dialect excel = new Dialect(",", "\"", null, true, false, "\r\n", QUOTE_MINIMAL, false, "excel");
        public static readonly Dialect excel_tab = new Dialect("\t", "\"", null, true, false, "\r\n", QUOTE_MINIMAL, false, "excel_tab");
        public static readonly Dialect unix_dialect = new Dialect(",", "\"", null, true, false, "\n", QUOTE_ALL, false, "unix_dialect");

        static readonly Dictionary<string, Dialect> Registry = new Dictionary<string, Dialect>
        {
            ["excel"] = excel, ["excel-tab"] = excel_tab, ["unix"] = unix_dialect,
        };

        public static void register_dialect(string name, object? dialect = null, string delimiter = Unset, string? quotechar = Unset, string? escapechar = Unset,
                                            bool? doublequote = null, bool? skipinitialspace = null, string lineterminator = Unset, long? quoting = null, bool? strict = null)
        {
            Registry[name] = Resolve(dialect, delimiter, quotechar, escapechar, doublequote, skipinitialspace, lineterminator, quoting, strict);
        }

        public static void unregister_dialect(string name) { if (!Registry.Remove(name)) throw new Error("unknown dialect"); }
        public static Dialect get_dialect(string name) => Registry.TryGetValue(name, out var d) ? d : throw new Error("unknown dialect");
        public static List<string> list_dialects() => Registry.Keys.ToList();

        static Dialect ReadDialect(object dialect)
        {
            if (dialect is Dialect native) return native;
            if (dialect is string name) return get_dialect(name);

            object? Attr(string key, object? fallback) => Builtins.getattr(dialect, key, fallback);
            string? Text(string key, string? fallback)
            {
                object? value = Attr(key, fallback);
                if (value == null || value is string) return (string?)value;
                throw new InvalidCastException($"\"{key}\" must be a string");
            }
            object? quoting = Attr("quoting", excel.quoting);
            if (quoting is not (long or int)) throw new InvalidCastException("\"quoting\" must be an integer");
            return new Dialect(Text("delimiter", excel.delimiter)!, Text("quotechar", excel.quotechar),
                Text("escapechar", excel.escapechar), Builtins.truthy(Attr("doublequote", excel.doublequote)),
                Builtins.truthy(Attr("skipinitialspace", excel.skipinitialspace)),
                Text("lineterminator", excel.lineterminator)!, Convert.ToInt64(quoting), Builtins.truthy(Attr("strict", excel.strict)));
        }

        static Dialect Resolve(object? dialect, string delimiter, string? quotechar, string? escapechar, bool? doublequote, bool? skipinitialspace,
                               string lineterminator, long? quoting, bool? strict)
        {
            var baseDialect = dialect switch
            {
                null => excel,
                string name => get_dialect(name),
                Dialect d => d,
                _ => ReadDialect(dialect),
            };
            return baseDialect.With(delimiter, quotechar, escapechar, doublequote, skipinitialspace, lineterminator, quoting, strict);
        }

        public static CsvReader reader(IEnumerable<string> csvfile, object? dialect = null, string delimiter = Unset, string? quotechar = Unset,
                                       string? escapechar = Unset, bool? doublequote = null, bool? skipinitialspace = null, string lineterminator = Unset,
                                       long? quoting = null, bool? strict = null) =>
            new CsvReader(csvfile, Resolve(dialect, delimiter, quotechar, escapechar, doublequote, skipinitialspace, lineterminator, quoting, strict));

        public static CsvWriter writer(object csvfile, object? dialect = null, string delimiter = Unset, string? quotechar = Unset,
                                       string? escapechar = Unset, bool? doublequote = null, bool? skipinitialspace = null, string lineterminator = Unset,
                                       long? quoting = null, bool? strict = null) =>
            new CsvWriter(csvfile, Resolve(dialect, delimiter, quotechar, escapechar, doublequote, skipinitialspace, lineterminator, quoting, strict));

        /// <summary>csv.DictReader: each record as a dict keyed by the field names (the first record unless given).</summary>
        public static CsvDictReader DictReader(IEnumerable<string> f, IEnumerable<string>? fieldnames = null, object? restkey = null, string? restval = null,
                                               object? dialect = null, string delimiter = Unset, string? quotechar = Unset, string? escapechar = Unset,
                                               bool? doublequote = null, bool? skipinitialspace = null, string lineterminator = Unset, long? quoting = null,
                                               bool? strict = null) =>
            new CsvDictReader(fieldnames, restkey, restval, dialect, reader(f, dialect, delimiter, quotechar, escapechar, doublequote, skipinitialspace, lineterminator, quoting, strict));

        /// <summary>csv.DictWriter: writes dicts as records in the order of fieldnames.</summary>
        public static CsvDictWriter DictWriter(object f, IEnumerable<string> fieldnames, object? restval = null, string extrasaction = "raise",
                                               object? dialect = null, string delimiter = Unset, string? quotechar = Unset, string? escapechar = Unset,
                                               bool? doublequote = null, bool? skipinitialspace = null, string lineterminator = Unset, long? quoting = null,
                                               bool? strict = null) =>
            new CsvDictWriter(fieldnames, restval, extrasaction, writer(f, dialect, delimiter, quotechar, escapechar, doublequote, skipinitialspace, lineterminator, quoting, strict));
    }
